use vstd::prelude::*;
use vstd::vec::*;

verus! {

spec fn vec_char_eq(v1: Vec<char>, v2: Vec<char>) -> bool {
    v1.len() == v2.len() &&
    forall|i: int| 0 <= i && i < v1.len() ==> v1[i] == v2[i]
}

spec fn prefix_matches(v1: Vec<char>, v2: Vec<char>, len: nat) -> bool
    requires
        len <= v1.len(),
        len <= v2.len(),
{
    forall|i: int| 0 <= i && i < len ==> v1[i] == v2[i]
}

fn solve(t: Vec<char>) -> (result: Vec<char>)
    requires
        t.len() >= 1,
    ensures
        result.len() == t.len(),
        vec_char_eq(result, t),
{
    // Create a new vector with the same content
    let mut result = Vec::new();
    let mut i: usize = 0;
    
    while i < t.len()
        invariant
            0 <= i <= t.len(),
            result.len() == i,
            forall|j: int| 0 <= j && j < i ==> result[j] == t[j],
    {
        result.push(t[i]);
        i = i + 1;
    }
    
    result
}

}